"""
One-Step Local Folder Updater for TradePilot NSE (1-Month Automated Paper Trial Journal).
Place inside your existing TradePilot_NSE folder (next to app.py) and run:
    python apply_paper_trial_update.py
"""
import json
from pathlib import Path

PATCH_FILES = json.loads("{\"analysis/paper_trial.py\": \"\\\"\\\"\\\"\\n1-Month Automated Paper Trading & Forward-Test Journal Engine for TradePilot NSE.\\nManages a dedicated \\u20b950,000 (configurable + top-up) forward-testing trial:\\n1. Checks all OPEN paper trial positions against the latest EOD bar for Stop-Loss, Target, or Time Exits.\\n2. Scans today's BUY WATCH signals sorted by Overall Score (highest first) and enters up to 1-3 top stocks.\\n3. If zero stocks have a BUY WATCH signal, records 0 entries for the day.\\n4. Logs every daily run, entry, exit, charges (0.18% round-trip), net P&L, and realized R-multiple in SQLite.\\n\\\"\\\"\\\"\\nfrom datetime import timedelta\\nfrom typing import Any, Dict, List, Optional\\nimport math\\nimport pandas as pd\\n\\nfrom data.database import DatabaseManager\\nfrom utils.helpers import now_ist\\nfrom utils.logging_config import get_logger\\n\\nlogger = get_logger(\\\"paper_trial\\\")\\n\\n\\ndef init_paper_trial_tables(db: DatabaseManager) -> None:\\n    with db.get_connection() as conn:\\n        conn.execute(\\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS paper_trial_config (\\n                id INTEGER PRIMARY KEY CHECK (id = 1),\\n                start_date TEXT NOT NULL,\\n                end_date TEXT NOT NULL,\\n                initial_capital REAL NOT NULL DEFAULT 50000.0,\\n                added_capital REAL NOT NULL DEFAULT 0.0,\\n                max_daily_entries INTEGER NOT NULL DEFAULT 3,\\n                max_open_positions INTEGER NOT NULL DEFAULT 6,\\n                risk_per_trade_pct REAL NOT NULL DEFAULT 1.5,\\n                max_holding_days INTEGER NOT NULL DEFAULT 15,\\n                is_active INTEGER NOT NULL DEFAULT 1\\n            )\\n        \\\"\\\"\\\")\\n        conn.execute(\\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS paper_trial_trades (\\n                trade_id INTEGER PRIMARY KEY AUTOINCREMENT,\\n                symbol TEXT NOT NULL,\\n                status TEXT NOT NULL DEFAULT 'OPEN',\\n                signal_date TEXT NOT NULL,\\n                entry_date TEXT NOT NULL,\\n                entry_price REAL NOT NULL,\\n                quantity INTEGER NOT NULL,\\n                stop_loss REAL NOT NULL,\\n                target_price REAL NOT NULL,\\n                risk_per_share REAL NOT NULL,\\n                planned_rr REAL NOT NULL,\\n                overall_score REAL NOT NULL,\\n                matched_strategies TEXT,\\n                exit_date TEXT,\\n                exit_price REAL,\\n                exit_reason TEXT,\\n                gross_pnl REAL DEFAULT 0.0,\\n                charges REAL DEFAULT 0.0,\\n                net_pnl REAL DEFAULT 0.0,\\n                return_pct REAL DEFAULT 0.0,\\n                realized_r REAL DEFAULT 0.0,\\n                notes TEXT\\n            )\\n        \\\"\\\"\\\")\\n        conn.execute(\\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS paper_trial_daily_logs (\\n                run_date TEXT PRIMARY KEY,\\n                buy_signals_count INTEGER NOT NULL,\\n                entries_taken INTEGER NOT NULL,\\n                exits_triggered INTEGER NOT NULL,\\n                equity_inr REAL NOT NULL,\\n                cash_inr REAL NOT NULL,\\n                summary_note TEXT NOT NULL\\n            )\\n        \\\"\\\"\\\")\\n        conn.commit()\\n\\n    # Seed default 1-month trial config if empty (starting next Monday or today)\\n    with db.get_connection() as conn:\\n        row = conn.execute(\\\"SELECT id FROM paper_trial_config WHERE id = 1\\\").fetchone()\\n        if not row:\\n            today = now_ist().date()\\n            # Default start date: upcoming Monday if weekend, else today\\n            days_until_mon = (7 - today.weekday()) % 7\\n            start_dt = today + timedelta(days=days_until_mon) if today.weekday() >= 5 else today\\n            end_dt = start_dt + timedelta(days=30)\\n            conn.execute(\\n                \\\"\\\"\\\"\\n                INSERT INTO paper_trial_config\\n                (id, start_date, end_date, initial_capital, added_capital, max_daily_entries,\\n                 max_open_positions, risk_per_trade_pct, max_holding_days, is_active)\\n                VALUES (1, ?, ?, 50000.0, 0.0, 3, 6, 1.5, 15, 1)\\n                \\\"\\\"\\\",\\n                (start_dt.strftime(\\\"%Y-%m-%d\\\"), end_dt.strftime(\\\"%Y-%m-%d\\\")),\\n            )\\n            conn.commit()\\n\\n\\ndef get_paper_trial_config(db: DatabaseManager) -> Dict[str, Any]:\\n    init_paper_trial_tables(db)\\n    with db.get_connection() as conn:\\n        row = conn.execute(\\\"SELECT * FROM paper_trial_config WHERE id = 1\\\").fetchone()\\n        return dict(row)\\n\\n\\ndef update_paper_trial_config(\\n    db: DatabaseManager,\\n    start_date: str,\\n    end_date: str,\\n    initial_capital: float,\\n    max_daily_entries: int,\\n    max_open_positions: int,\\n    risk_per_trade_pct: float,\\n    max_holding_days: int,\\n    is_active: bool = True,\\n) -> None:\\n    init_paper_trial_tables(db)\\n    with db.get_connection() as conn:\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            UPDATE paper_trial_config\\n            SET start_date = ?, end_date = ?, initial_capital = ?, max_daily_entries = ?,\\n                max_open_positions = ?, risk_per_trade_pct = ?, max_holding_days = ?, is_active = ?\\n            WHERE id = 1\\n            \\\"\\\"\\\",\\n            (\\n                start_date,\\n                end_date,\\n                float(initial_capital),\\n                int(max_daily_entries),\\n                int(max_open_positions),\\n                float(risk_per_trade_pct),\\n                int(max_holding_days),\\n                1 if is_active else 0,\\n            ),\\n        )\\n        conn.commit()\\n\\n\\ndef add_trial_capital(db: DatabaseManager, amount_inr: float) -> None:\\n    init_paper_trial_tables(db)\\n    if amount_inr <= 0:\\n        return\\n    with db.get_connection() as conn:\\n        conn.execute(\\\"UPDATE paper_trial_config SET added_capital = added_capital + ? WHERE id = 1\\\", (float(amount_inr),))\\n        conn.commit()\\n\\n\\ndef reset_paper_trial(db: DatabaseManager, initial_capital: float = 50000.0, start_date: Optional[str] = None) -> None:\\n    init_paper_trial_tables(db)\\n    today = now_ist().date()\\n    s_dt = pd.to_datetime(start_date).date() if start_date else today\\n    e_dt = s_dt + timedelta(days=30)\\n    with db.get_connection() as conn:\\n        conn.execute(\\\"DELETE FROM paper_trial_trades\\\")\\n        conn.execute(\\\"DELETE FROM paper_trial_daily_logs\\\")\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            UPDATE paper_trial_config\\n            SET start_date = ?, end_date = ?, initial_capital = ?, added_capital = 0.0, is_active = 1\\n            WHERE id = 1\\n            \\\"\\\"\\\",\\n            (s_dt.strftime(\\\"%Y-%m-%d\\\"), e_dt.strftime(\\\"%Y-%m-%d\\\"), float(initial_capital)),\\n        )\\n        conn.commit()\\n\\n\\ndef run_daily_paper_trial_step(db: DatabaseManager, run_date_str: Optional[str] = None) -> Dict[str, Any]:\\n    \\\"\\\"\\\"\\n    Executes one daily paper-trading cycle:\\n    1. Checks OPEN positions against latest market bar for exits (Stop-Loss, Target, or Time Exit).\\n    2. Checks today's BUY WATCH signals sorted by Overall Score descending and enters top 1-3 stocks.\\n    3. If 0 BUY WATCH signals exist, takes 0 entries.\\n    \\\"\\\"\\\"\\n    init_paper_trial_tables(db)\\n    cfg = get_paper_trial_config(db)\\n    if not cfg.get(\\\"is_active\\\", 1):\\n        return {\\\"skipped\\\": True, \\\"reason\\\": \\\"Paper trial is currently paused in settings.\\\"}\\n\\n    screen_df = db.get_all_screening_results()\\n    if screen_df.empty:\\n        return {\\\"skipped\\\": True, \\\"reason\\\": \\\"No screening results in database yet.\\\"}\\n\\n    latest_bar_date = str(screen_df[\\\"trade_date\\\"].max())\\n    eff_date = run_date_str or latest_bar_date\\n\\n    # 1. Process Exits on OPEN positions\\n    exits_triggered = 0\\n    exit_notes: List[str] = []\\n\\n    with db.get_connection() as conn:\\n        open_rows = conn.execute(\\\"SELECT * FROM paper_trial_trades WHERE status = 'OPEN'\\\").fetchall()\\n\\n    for row in open_rows:\\n        pos = dict(row)\\n        sym = pos[\\\"symbol\\\"]\\n        # Do not exit on the exact same bar it was entered\\n        if pos[\\\"entry_date\\\"] >= eff_date:\\n            continue\\n\\n        hist = db.get_historical_prices(sym, limit_days=30)\\n        if hist.empty:\\n            continue\\n\\n        # Check latest bar (or bars since entry)\\n        recent_bars = hist[hist[\\\"trade_date\\\"] > pos[\\\"entry_date\\\"]]\\n        if recent_bars.empty:\\n            continue\\n\\n        last_bar = recent_bars.iloc[-1]\\n        bar_dt = str(last_bar[\\\"trade_date\\\"])\\n        low_p = float(last_bar[\\\"low\\\"])\\n        high_p = float(last_bar[\\\"high\\\"])\\n        close_p = float(last_bar[\\\"close\\\"])\\n        open_p = float(last_bar[\\\"open\\\"])\\n        bars_held = len(recent_bars)\\n\\n        exit_px = None\\n        exit_reason = None\\n\\n        if open_p <= pos[\\\"stop_loss\\\"]:\\n            exit_px = open_p\\n            exit_reason = \\\"Gap-Down Stop-Loss\\\"\\n        elif low_p <= pos[\\\"stop_loss\\\"]:\\n            exit_px = pos[\\\"stop_loss\\\"]\\n            exit_reason = \\\"Stop-Loss Hit\\\"\\n        elif open_p >= pos[\\\"target_price\\\"]:\\n            exit_px = open_p\\n            exit_reason = \\\"Gap-Up Target Hit\\\"\\n        elif high_p >= pos[\\\"target_price\\\"]:\\n            exit_px = pos[\\\"target_price\\\"]\\n            exit_reason = \\\"Target 2 Hit\\\"\\n        elif bars_held >= int(cfg[\\\"max_holding_days\\\"]):\\n            exit_px = close_p\\n            exit_reason = f\\\"Time Exit ({cfg['max_holding_days']}d)\\\"\\n\\n        if exit_px is not None:\\n            qty = int(pos[\\\"quantity\\\"])\\n            gross_pnl = (exit_px - pos[\\\"entry_price\\\"]) * qty\\n            charges = (pos[\\\"entry_price\\\"] + exit_px) * qty * 0.0018  # 0.18% realistic delivery STT/brokerage\\n            net_pnl = gross_pnl - charges\\n            invested = pos[\\\"entry_price\\\"] * qty\\n            ret_pct = (net_pnl / invested) * 100.0 if invested > 0 else 0.0\\n            realized_r = (exit_px - pos[\\\"entry_price\\\"]) / pos[\\\"risk_per_share\\\"] if pos[\\\"risk_per_share\\\"] > 0 else 0.0\\n\\n            with db.get_connection() as conn:\\n                conn.execute(\\n                    \\\"\\\"\\\"\\n                    UPDATE paper_trial_trades\\n                    SET status = 'CLOSED', exit_date = ?, exit_price = ?, exit_reason = ?,\\n                        gross_pnl = ?, charges = ?, net_pnl = ?, return_pct = ?, realized_r = ?\\n                    WHERE trade_id = ?\\n                    \\\"\\\"\\\",\\n                    (\\n                        bar_dt,\\n                        round(exit_px, 2),\\n                        exit_reason,\\n                        round(gross_pnl, 2),\\n                        round(charges, 2),\\n                        round(net_pnl, 2),\\n                        round(ret_pct, 2),\\n                        round(realized_r, 2),\\n                        pos[\\\"trade_id\\\"],\\n                    ),\\n                )\\n                conn.commit()\\n            exits_triggered += 1\\n            exit_notes.append(f\\\"EXIT {sym} @ \\u20b9{exit_px:,.2f} ({exit_reason}, Net \\u20b9{net_pnl:+,.2f})\\\")\\n\\n    # 2. Compute available cash & current open count before entries\\n    analytics = get_paper_trial_analytics(db)\\n    cash_available = analytics[\\\"cash_available\\\"]\\n    current_equity = analytics[\\\"current_equity\\\"]\\n    open_symbols = set(analytics[\\\"open_df\\\"][\\\"symbol\\\"].tolist()) if not analytics[\\\"open_df\\\"].empty else set()\\n    open_count = len(open_symbols)\\n\\n    # 3. Scan BUY WATCH signals ordered by highest score\\n    buy_df = screen_df[screen_df[\\\"signal\\\"] == \\\"BUY WATCH\\\"].sort_values(\\\"overall_score\\\", ascending=False)\\n    buy_signals_count = len(buy_df)\\n\\n    entries_taken = 0\\n    entry_notes: List[str] = []\\n    max_new = int(cfg[\\\"max_daily_entries\\\"])\\n    max_open = int(cfg[\\\"max_open_positions\\\"])\\n    risk_pct = float(cfg[\\\"risk_per_trade_pct\\\"])\\n\\n    if buy_signals_count == 0:\\n        entry_notes.append(\\\"No BUY WATCH signals today \\u2014 0 entries taken.\\\")\\n    else:\\n        for _, cand in buy_df.iterrows():\\n            if entries_taken >= max_new or open_count >= max_open:\\n                break\\n            sym = cand[\\\"symbol\\\"]\\n            if sym in open_symbols:\\n                continue\\n\\n            entry_px = float(cand[\\\"close_price\\\"])\\n            sl_px = float(cand[\\\"stop_loss\\\"])\\n            tgt_px = float(cand[\\\"target_2\\\"])\\n            risk_per_sh = max(entry_px - sl_px, entry_px * 0.01)\\n\\n            # Position sizing: risk_pct of equity, capped at 35% of total equity and available cash\\n            max_risk_inr = current_equity * (risk_pct / 100.0)\\n            qty_by_risk = math.floor(max_risk_inr / risk_per_sh)\\n            qty_by_alloc = math.floor((current_equity * 0.35) / entry_px)\\n            qty_by_cash = math.floor(cash_available / entry_px)\\n            qty = min(qty_by_risk if qty_by_risk > 0 else qty_by_alloc, qty_by_alloc, qty_by_cash)\\n\\n            if qty <= 0:\\n                continue\\n\\n            cost = qty * entry_px\\n            planned_rr = round((tgt_px - entry_px) / risk_per_sh, 2)\\n\\n            with db.get_connection() as conn:\\n                conn.execute(\\n                    \\\"\\\"\\\"\\n                    INSERT INTO paper_trial_trades\\n                    (symbol, status, signal_date, entry_date, entry_price, quantity, stop_loss, target_price,\\n                     risk_per_share, planned_rr, overall_score, matched_strategies, notes)\\n                    VALUES (?, 'OPEN', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\\n                    \\\"\\\"\\\",\\n                    (\\n                        sym,\\n                        str(cand[\\\"trade_date\\\"]),\\n                        eff_date,\\n                        round(entry_px, 2),\\n                        int(qty),\\n                        round(sl_px, 2),\\n                        round(tgt_px, 2),\\n                        round(risk_per_sh, 2),\\n                        planned_rr,\\n                        round(float(cand[\\\"overall_score\\\"]), 2),\\n                        str(cand.get(\\\"matched_strategies\\\", \\\"\\\")),\\n                        f\\\"Auto-entry Rank #{entries_taken + 1} (Score {cand['overall_score']:.1f})\\\",\\n                    ),\\n                )\\n                conn.commit()\\n\\n            cash_available -= cost\\n            open_symbols.add(sym)\\n            open_count += 1\\n            entries_taken += 1\\n            entry_notes.append(f\\\"ENTRY {sym}: {qty} sh @ \\u20b9{entry_px:,.2f} (SL \\u20b9{sl_px:,.2f}, T2 \\u20b9{tgt_px:,.2f})\\\")\\n\\n        if entries_taken == 0 and buy_signals_count > 0:\\n            entry_notes.append(\\n                f\\\"{buy_signals_count} BUY WATCH signals found, but 0 new entries taken (already open, max positions {max_open} reached, or insufficient cash \\u20b9{cash_available:,.0f}).\\\"\\n            )\\n\\n    # 4. Refresh analytics & save daily log\\n    post_analytics = get_paper_trial_analytics(db)\\n    all_notes = \\\" | \\\".join(exit_notes + entry_notes)\\n\\n    with db.get_connection() as conn:\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            INSERT INTO paper_trial_daily_logs\\n            (run_date, buy_signals_count, entries_taken, exits_triggered, equity_inr, cash_inr, summary_note)\\n            VALUES (?, ?, ?, ?, ?, ?, ?)\\n            ON CONFLICT(run_date) DO UPDATE SET\\n                buy_signals_count = excluded.buy_signals_count,\\n                entries_taken = excluded.entries_taken,\\n                exits_triggered = excluded.exits_triggered,\\n                equity_inr = excluded.equity_inr,\\n                cash_inr = excluded.cash_inr,\\n                summary_note = excluded.summary_note\\n            \\\"\\\"\\\",\\n            (\\n                eff_date,\\n                buy_signals_count,\\n                entries_taken,\\n                exits_triggered,\\n                round(post_analytics[\\\"current_equity\\\"], 2),\\n                round(post_analytics[\\\"cash_available\\\"], 2),\\n                all_notes,\\n            ),\\n        )\\n        conn.commit()\\n\\n    return {\\n        \\\"skipped\\\": False,\\n        \\\"run_date\\\": eff_date,\\n        \\\"buy_signals_count\\\": buy_signals_count,\\n        \\\"entries_taken\\\": entries_taken,\\n        \\\"exits_triggered\\\": exits_triggered,\\n        \\\"summary_note\\\": all_notes,\\n    }\\n\\n\\ndef get_paper_trial_analytics(db: DatabaseManager) -> Dict[str, Any]:\\n    init_paper_trial_tables(db)\\n    cfg = get_paper_trial_config(db)\\n\\n    with db.get_connection() as conn:\\n        open_df = pd.read_sql_query(\\n            \\\"\\\"\\\"\\n            SELECT p.*, s.close_price as current_price, s.daily_pct_change\\n            FROM paper_trial_trades p\\n            LEFT JOIN screening_results s ON p.symbol = s.symbol\\n            WHERE p.status = 'OPEN'\\n            ORDER BY p.entry_date DESC, p.trade_id DESC\\n            \\\"\\\"\\\",\\n            conn,\\n        )\\n        closed_df = pd.read_sql_query(\\n            \\\"SELECT * FROM paper_trial_trades WHERE status = 'CLOSED' ORDER BY exit_date DESC, trade_id DESC\\\",\\n            conn,\\n        )\\n        logs_df = pd.read_sql_query(\\\"SELECT * FROM paper_trial_daily_logs ORDER BY run_date DESC\\\", conn)\\n\\n    base_capital = float(cfg[\\\"initial_capital\\\"]) + float(cfg[\\\"added_capital\\\"])\\n    realized_pnl = float(closed_df[\\\"net_pnl\\\"].sum()) if not closed_df.empty else 0.0\\n\\n    deployed_cost = 0.0\\n    unrealized_pnl = 0.0\\n    if not open_df.empty:\\n        open_df[\\\"current_price\\\"] = open_df[\\\"current_price\\\"].fillna(open_df[\\\"entry_price\\\"])\\n        open_df[\\\"invested_inr\\\"] = (open_df[\\\"entry_price\\\"] * open_df[\\\"quantity\\\"]).round(2)\\n        open_df[\\\"unrealized_pnl\\\"] = ((open_df[\\\"current_price\\\"] - open_df[\\\"entry_price\\\"]) * open_df[\\\"quantity\\\"]).round(2)\\n        open_df[\\\"unrealized_pct\\\"] = (((open_df[\\\"current_price\\\"] - open_df[\\\"entry_price\\\"]) / open_df[\\\"entry_price\\\"]) * 100.0).round(2)\\n        open_df[\\\"current_r\\\"] = ((open_df[\\\"current_price\\\"] - open_df[\\\"entry_price\\\"]) / open_df[\\\"risk_per_share\\\"]).round(2)\\n        deployed_cost = float(open_df[\\\"invested_inr\\\"].sum())\\n        unrealized_pnl = float(open_df[\\\"unrealized_pnl\\\"].sum())\\n\\n    cash_available = base_capital + realized_pnl - deployed_cost\\n    current_equity = base_capital + realized_pnl + unrealized_pnl\\n    total_pnl = realized_pnl + unrealized_pnl\\n    total_return_pct = (total_pnl / base_capital) * 100.0 if base_capital > 0 else 0.0\\n\\n    win_rate = 0.0\\n    profit_factor = 0.0\\n    avg_r = 0.0\\n    if not closed_df.empty:\\n        wins = closed_df[closed_df[\\\"net_pnl\\\"] > 0]\\n        losses = closed_df[closed_df[\\\"net_pnl\\\"] <= 0]\\n        win_rate = (len(wins) / len(closed_df)) * 100.0\\n        gp = float(wins[\\\"net_pnl\\\"].sum()) if not wins.empty else 0.0\\n        gl = abs(float(losses[\\\"net_pnl\\\"].sum())) if not losses.empty else 0.0\\n        profit_factor = round(gp / gl, 2) if gl > 0 else (9.99 if gp > 0 else 0.0)\\n        avg_r = round(float(closed_df[\\\"realized_r\\\"].mean()), 2)\\n\\n    return {\\n        \\\"config\\\": cfg,\\n        \\\"initial_capital\\\": float(cfg[\\\"initial_capital\\\"]),\\n        \\\"added_capital\\\": float(cfg[\\\"added_capital\\\"]),\\n        \\\"total_capital\\\": round(base_capital, 2),\\n        \\\"cash_available\\\": round(cash_available, 2),\\n        \\\"deployed_capital\\\": round(deployed_cost, 2),\\n        \\\"current_equity\\\": round(current_equity, 2),\\n        \\\"realized_pnl\\\": round(realized_pnl, 2),\\n        \\\"unrealized_pnl\\\": round(unrealized_pnl, 2),\\n        \\\"total_pnl\\\": round(total_pnl, 2),\\n        \\\"total_return_pct\\\": round(total_return_pct, 2),\\n        \\\"win_rate_pct\\\": round(win_rate, 2),\\n        \\\"profit_factor\\\": profit_factor,\\n        \\\"avg_realized_r\\\": avg_r,\\n        \\\"open_df\\\": open_df,\\n        \\\"closed_df\\\": closed_df,\\n        \\\"logs_df\\\": logs_df,\\n    }\\n\", \"dashboard/paper_trial_page.py\": \"\\\"\\\"\\\"\\nPage 8: 1-Month Paper Trial Journal & Automated Forward-Testing Analytics.\\nTracks daily automated entries (top 1-3 BUY WATCH stocks by score) and exits (SL/Target/Time),\\nstarting from \\u20b950,000 capital with optional top-ups and full P&L / Risk-Reward analytics.\\n\\\"\\\"\\\"\\nimport streamlit as st\\nimport plotly.graph_objects as go\\nimport pandas as pd\\n\\nfrom data.database import DatabaseManager\\nfrom analysis.paper_trial import (\\n    get_paper_trial_analytics,\\n    run_daily_paper_trial_step,\\n    add_trial_capital,\\n    update_paper_trial_config,\\n    reset_paper_trial,\\n)\\nfrom utils.helpers import format_inr, format_pct\\n\\n\\ndef render_paper_trial_page(db: DatabaseManager) -> None:\\n    st.title(\\\"\\ud83e\\uddea 1-Month Automated Paper Trial & Forward-Test Journal\\\")\\n    st.caption(\\n        \\\"Automatically enters the top 1\\u20133 BUY WATCH stocks by score each trading day (0 entries when no BUY WATCH triggers), \\\"\\n        \\\"monitors Stop-Loss / Target 2 / Time exits daily, and tracks real P&L & Risk/Reward.\\\"\\n    )\\n\\n    data = get_paper_trial_analytics(db)\\n    cfg = data[\\\"config\\\"]\\n\\n    # Top Action Bar\\n    a1, a2, a3, a4 = st.columns([1.4, 1.4, 1.2, 1.2])\\n    with a1:\\n        st.info(f\\\"\\ud83d\\udcc5 **Trial Window:** `{cfg['start_date']}` to `{cfg['end_date']}`\\\")\\n    with a2:\\n        if st.button(\\\"\\u25b6\\ufe0f Run Today's Paper Trial Step Now\\\", type=\\\"primary\\\", use_container_width=True):\\n            res = run_daily_paper_trial_step(db)\\n            if res.get(\\\"skipped\\\"):\\n                st.warning(res.get(\\\"reason\\\"))\\n            else:\\n                st.success(\\n                    f\\\"Completed for {res['run_date']}: {res['entries_taken']} entries, {res['exits_triggered']} exits. \\\"\\n                    f\\\"({res['summary_note']})\\\"\\n                )\\n                st.rerun()\\n    with a3:\\n        with st.popover(\\\"\\ud83d\\udcb5 Add Capital (Top-Up)\\\", use_container_width=True):\\n            topup = st.number_input(\\\"Add Capital Amount (\\u20b9)\\\", min_value=1000.0, value=25000.0, step=5000.0)\\n            if st.button(\\\"Confirm Add Capital\\\"):\\n                add_trial_capital(db, topup)\\n                st.success(f\\\"Added \\u20b9{topup:,.2f} to Paper Trial capital!\\\")\\n                st.rerun()\\n    with a4:\\n        with st.popover(\\\"\\u2699\\ufe0f Trial Rules & Reset\\\", use_container_width=True):\\n            with st.form(\\\"trial_cfg_form\\\"):\\n                new_start = st.date_input(\\\"Start Date\\\", value=pd.to_datetime(cfg[\\\"start_date\\\"]).date())\\n                new_end = st.date_input(\\\"End Date\\\", value=pd.to_datetime(cfg[\\\"end_date\\\"]).date())\\n                new_init_cap = st.number_input(\\\"Starting Capital (\\u20b9)\\\", min_value=10000.0, value=float(cfg[\\\"initial_capital\\\"]), step=5000.0)\\n                new_max_daily = st.slider(\\\"Max New Entries Per Day (1\\u20133)\\\", 1, 5, int(cfg[\\\"max_daily_entries\\\"]))\\n                new_max_open = st.slider(\\\"Max Concurrent Open Positions\\\", 1, 12, int(cfg[\\\"max_open_positions\\\"]))\\n                new_risk_pct = st.number_input(\\\"Risk % Per Trade\\\", 0.5, 5.0, float(cfg[\\\"risk_per_trade_pct\\\"]), 0.25)\\n                new_hold = st.slider(\\\"Max Holding Days\\\", 5, 30, int(cfg[\\\"max_holding_days\\\"]))\\n                new_active = st.checkbox(\\\"Trial Active (Auto-run in EOD)\\\", value=bool(cfg[\\\"is_active\\\"]))\\n                if st.form_submit_button(\\\"\\ud83d\\udcbe Save Trial Rules\\\"):\\n                    update_paper_trial_config(\\n                        db,\\n                        new_start.strftime(\\\"%Y-%m-%d\\\"),\\n                        new_end.strftime(\\\"%Y-%m-%d\\\"),\\n                        new_init_cap,\\n                        new_max_daily,\\n                        new_max_open,\\n                        new_risk_pct,\\n                        new_hold,\\n                        new_active,\\n                    )\\n                    st.success(\\\"Paper Trial rules updated!\\\")\\n                    st.rerun()\\n            st.divider()\\n            if st.button(\\\"\\ud83d\\udd04 Reset 1-Month Trial to \\u20b950,000\\\", type=\\\"secondary\\\"):\\n                reset_paper_trial(db, initial_capital=50000.0)\\n                st.warning(\\\"Paper Trial journal reset to \\u20b950,000!\\\")\\n                st.rerun()\\n\\n    st.divider()\\n\\n    # KPI Row 1: Capital & P&L\\n    k1, k2, k3, k4, k5 = st.columns(5)\\n    k1.metric(\\\"Total Funded Capital\\\", format_inr(data[\\\"total_capital\\\"]), f\\\"Base \\u20b9{data['initial_capital']:,.0f} + Added \\u20b9{data['added_capital']:,.0f}\\\")\\n    k2.metric(\\\"Current Trial Equity\\\", format_inr(data[\\\"current_equity\\\"]), format_pct(data[\\\"total_return_pct\\\"]))\\n    k3.metric(\\\"Available Cash\\\", format_inr(data[\\\"cash_available\\\"]), f\\\"Deployed: {format_inr(data['deployed_capital'])}\\\")\\n    k4.metric(\\\"Realized Net P&L\\\", format_inr(data[\\\"realized_pnl\\\"]), f\\\"Unrealized: {format_inr(data['unrealized_pnl'])}\\\")\\n    k5.metric(\\\"Win Rate & Avg R:R\\\", f\\\"{data['win_rate_pct']:.1f}%\\\", f\\\"PF: {data['profit_factor']:.2f} | Avg {data['avg_realized_r']:+.2f}R\\\")\\n\\n    # Equity Curve Chart\\n    logs_df = data[\\\"logs_df\\\"]\\n    if not logs_df.empty:\\n        plot_logs = logs_df.sort_values(\\\"run_date\\\")\\n        fig_eq = go.Figure()\\n        fig_eq.add_trace(\\n            go.Scatter(\\n                x=plot_logs[\\\"run_date\\\"],\\n                y=plot_logs[\\\"equity_inr\\\"],\\n                mode=\\\"lines+markers\\\",\\n                name=\\\"Paper Trial Equity (\\u20b9)\\\",\\n                line=dict(color=\\\"#10b981\\\", width=2.5),\\n            )\\n        )\\n        fig_eq.add_hline(y=data[\\\"total_capital\\\"], line_dash=\\\"dot\\\", line_color=\\\"#9ca3af\\\", annotation_text=\\\"Funded Capital\\\")\\n        fig_eq.update_layout(title=\\\"1-Month Paper Trial Equity Curve (\\u20b9)\\\", height=320, template=\\\"plotly_dark\\\", margin=dict(l=15, r=15, t=40, b=20))\\n        st.plotly_chart(fig_eq, use_container_width=True)\\n\\n    # Tabs for Open Positions, Closed Trades, Daily Run Log\\n    tab_open, tab_closed, tab_logs = st.tabs([\\\"\\ud83d\\udcc2 Open Trial Positions\\\", \\\"\\ud83d\\udcdc Closed Trades & R:R Analysis\\\", \\\"\\ud83d\\uddd3\\ufe0f Daily Signal & Execution Log\\\"])\\n\\n    with tab_open:\\n        open_df = data[\\\"open_df\\\"]\\n        if open_df.empty:\\n            st.info(\\\"No open paper trial positions right now.\\\")\\n        else:\\n            st.dataframe(open_df, use_container_width=True, hide_index=True)\\n\\n    with tab_closed:\\n        closed_df = data[\\\"closed_df\\\"]\\n        if closed_df.empty:\\n            st.info(\\\"No closed paper trial trades yet. Trades close automatically when Stop-Loss, Target 2, or Max Holding Days is reached.\\\")\\n        else:\\n            st.dataframe(closed_df, use_container_width=True, hide_index=True)\\n            csv_bytes = closed_df.to_csv(index=False).encode(\\\"utf-8\\\")\\n            st.download_button(\\n                \\\"\\ud83d\\udce5 Export Closed Trial Trades (CSV)\\\",\\n                data=csv_bytes,\\n                file_name=\\\"tradepilot_paper_trial_trades.csv\\\",\\n                mime=\\\"text/csv\\\",\\n            )\\n\\n    with tab_logs:\\n        if logs_df.empty:\\n            st.info(\\\"No daily trial logs yet. Click **Run Today's Paper Trial Step Now** or let the 16:15 IST scheduler run.\\\")\\n        else:\\n            st.dataframe(logs_df, use_container_width=True, hide_index=True)\\n\", \"app.py\": \"\\\"\\\"\\\"\\nMain Streamlit Entry Point for TradePilot NSE.\\nRun locally via:\\n    streamlit run app.py\\nAccessible at:\\n    http://localhost:8501\\n\\\"\\\"\\\"\\nimport streamlit as st\\nfrom config import DISCLAIMER_TEXT\\nfrom data.database import DatabaseManager\\nfrom data.market_data import MarketDataService\\nfrom analysis.pipeline import run_full_screening_pipeline\\nfrom utils.helpers import evaluate_data_freshness\\n\\nfrom dashboard.overview import render_overview_page\\nfrom dashboard.screener import render_screener_page\\nfrom dashboard.stock_detail import render_stock_detail_page\\nfrom dashboard.opportunities import render_opportunities_page\\nfrom dashboard.portfolio import render_portfolio_page\\nfrom dashboard.backtesting_page import render_backtesting_page\\nfrom dashboard.settings_page import render_settings_page\\nfrom dashboard.paper_trial_page import render_paper_trial_page\\n\\nst.set_page_config(\\n    page_title=\\\"TradePilot NSE | Short-Term Equity Intelligence\\\",\\n    page_icon=\\\"\\ud83d\\udcc8\\\",\\n    layout=\\\"wide\\\",\\n    initial_sidebar_state=\\\"expanded\\\",\\n)\\n\\n\\n@st.cache_resource\\ndef get_db() -> DatabaseManager:\\n    return DatabaseManager()\\n\\n\\ndef apply_custom_css(theme_mode: str = \\\"Dark\\\") -> None:\\n    if theme_mode == \\\"Dark\\\":\\n        bg_card = \\\"#111827\\\"\\n        border_col = \\\"#1f2937\\\"\\n        text_col = \\\"#f3f4f6\\\"\\n    else:\\n        bg_card = \\\"#ffffff\\\"\\n        border_col = \\\"#e5e7eb\\\"\\n        text_col = \\\"#111827\\\"\\n\\n    st.markdown(\\n        f\\\"\\\"\\\"\\n        <style>\\n        .tp-card {{\\n            background-color: {bg_card};\\n            border: 1px solid {border_col};\\n            border-radius: 10px;\\n            padding: 16px;\\n            margin-bottom: 12px;\\n            color: {text_col};\\n        }}\\n        .badge-buy {{\\n            background-color: rgba(16, 185, 129, 0.18);\\n            color: #10b981;\\n            border: 1px solid #10b981;\\n            padding: 3px 10px;\\n            border-radius: 999px;\\n            font-weight: 700;\\n            font-size: 0.8rem;\\n        }}\\n        .badge-hold {{\\n            background-color: rgba(245, 158, 11, 0.18);\\n            color: #f59e0b;\\n            border: 1px solid #f59e0b;\\n            padding: 3px 10px;\\n            border-radius: 999px;\\n            font-weight: 700;\\n            font-size: 0.8rem;\\n        }}\\n        .badge-avoid {{\\n            background-color: rgba(239, 68, 68, 0.18);\\n            color: #ef4444;\\n            border: 1px solid #ef4444;\\n            padding: 3px 10px;\\n            border-radius: 999px;\\n            font-weight: 700;\\n            font-size: 0.8rem;\\n        }}\\n        .disclaimer-box {{\\n            font-size: 0.78rem;\\n            opacity: 0.85;\\n            border-left: 3px solid #f59e0b;\\n            padding-left: 10px;\\n            margin-top: 16px;\\n        }}\\n        </style>\\n        \\\"\\\"\\\",\\n        unsafe_allow_html=True,\\n    )\\n\\n\\ndef main() -> None:\\n    db = get_db()\\n    market_service = MarketDataService(db)\\n\\n    with st.sidebar:\\n        st.markdown(\\\"## \\ud83d\\udcc8 TradePilot NSE\\\")\\n        st.caption(\\\"Systematic Short-Term NSE Stock Screening & Risk Engine\\\")\\n\\n        theme_choice = st.radio(\\\"UI Theme Accent\\\", [\\\"Dark\\\", \\\"Light\\\"], horizontal=True, index=0)\\n        apply_custom_css(theme_choice)\\n\\n        page = st.radio(\\n            \\\"Navigation\\\",\\n            [\\n                \\\"1. Main Dashboard\\\",\\n                \\\"2. Stock Screener\\\",\\n                \\\"3. Stock Detail Analysis\\\",\\n                \\\"4. Trading Opportunities\\\",\\n                \\\"5. Portfolio & Watchlist\\\",\\n                \\\"6. Strategy Backtesting\\\",\\n                \\\"7. Custom Settings & Universe\\\",\\n                \\\"8. 1-Month Paper Trial Journal\\\",\\n            ],\\n        )\\n\\n        st.divider()\\n        st.subheader(\\\"\\ud83d\\udd04 Market Data Controls\\\")\\n\\n        last_log = db.get_last_update_log()\\n        latest_dt = db.get_latest_trade_date(\\\"RELIANCE\\\")\\n        fresh_label, fresh_color = evaluate_data_freshness(latest_dt)\\n        st.markdown(f\\\"**Data Status:** :{fresh_color}[**{fresh_label}**]\\\")\\n        if latest_dt:\\n            st.caption(f\\\"Latest NSE Bar Date: `{latest_dt}`\\\")\\n        if last_log:\\n            st.caption(f\\\"Last Sync: `{last_log['completed_at'][:19].replace('T', ' ')}`\\\")\\n\\n        col_btn1, col_btn2 = st.columns(2)\\n        with col_btn1:\\n            if st.button(\\\"\\u26a1 Smart Sync\\\", use_container_width=True, help=\\\"Fetches EOD updates only if newer bars exist\\\"):\\n                prog = st.progress(0, text=\\\"Checking NSE EOD data...\\\")\\n                res = market_service.refresh_stock_universe(\\n                    force=False,\\n                    fetch_fundamentals=True,\\n                    progress_callback=lambda cur, tot, sym: prog.progress(cur / tot, text=f\\\"Syncing {sym} ({cur}/{tot})\\\"),\\n                )\\n                prog.progress(1.0, text=\\\"Running indicator & scoring engine...\\\")\\n                run_full_screening_pipeline(db)\\n                prog.empty()\\n                st.success(f\\\"Sync complete! {res['details']}\\\")\\n                st.rerun()\\n\\n        with col_btn2:\\n            if st.button(\\\"\\ud83d\\udd01 Force Refresh\\\", use_container_width=True, help=\\\"Forces full re-download & re-scoring\\\"):\\n                prog = st.progress(0, text=\\\"Forcing full NSE download...\\\")\\n                res = market_service.refresh_stock_universe(\\n                    force=True,\\n                    fetch_fundamentals=True,\\n                    progress_callback=lambda cur, tot, sym: prog.progress(cur / tot, text=f\\\"Downloading {sym} ({cur}/{tot})\\\"),\\n                )\\n                prog.progress(1.0, text=\\\"Recomputing indicators & rankings...\\\")\\n                run_full_screening_pipeline(db)\\n                prog.empty()\\n                st.success(f\\\"Full refresh complete! {res['details']}\\\")\\n                st.rerun()\\n\\n        if st.button(\\\"\\ud83e\\uddee Re-Score Universe Only\\\", use_container_width=True, help=\\\"Recalculates indicators and scores from local SQLite DB\\\"):\\n            with st.spinner(\\\"Recalculating technicals, strategies, and 100-pt scores...\\\"):\\n                stats = run_full_screening_pipeline(db)\\n            st.success(f\\\"Scored {stats['processed']} NSE stocks.\\\")\\n            st.rerun()\\n\\n        st.markdown(f'<div class=\\\"disclaimer-box\\\">{DISCLAIMER_TEXT}</div>', unsafe_allow_html=True)\\n\\n    # Route to selected page\\n    if page.startswith(\\\"1.\\\"):\\n        render_overview_page(db, market_service)\\n    elif page.startswith(\\\"2.\\\"):\\n        render_screener_page(db)\\n    elif page.startswith(\\\"3.\\\"):\\n        render_stock_detail_page(db)\\n    elif page.startswith(\\\"4.\\\"):\\n        render_opportunities_page(db)\\n    elif page.startswith(\\\"5.\\\"):\\n        render_portfolio_page(db)\\n    elif page.startswith(\\\"6.\\\"):\\n        render_backtesting_page(db)\\n    elif page.startswith(\\\"7.\\\"):\\n        render_settings_page(db)\\n    elif page.startswith(\\\"8.\\\"):\\n        render_paper_trial_page(db)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\", \"eod_auto_update.py\": \"\\\"\\\"\\\"\\nAutomated End-of-Day Update, Daily Screening, 1-Month Paper Trial & Telegram Alert Runner for TradePilot NSE.\\nCan be executed from the command line or scheduled via Windows Task Scheduler at 16:15 IST every weekday:\\n    python eod_auto_update.py\\n\\\"\\\"\\\"\\nimport argparse\\nfrom pathlib import Path\\nfrom config import EXPORTS_DIR\\nfrom data.database import DatabaseManager\\nfrom data.market_data import MarketDataService\\nfrom analysis.pipeline import run_full_screening_pipeline\\nfrom analysis.paper_trial import run_daily_paper_trial_step\\nfrom utils.telegram_notifier import dispatch_eod_telegram_alert\\nfrom utils.logging_config import get_logger\\nfrom utils.helpers import now_ist\\n\\nlogger = get_logger(\\\"eod_automation\\\")\\n\\n\\ndef run_eod_job(force_refresh: bool = False, send_telegram: bool = True, run_paper_trial: bool = True) -> dict:\\n    logger.info(\\\"Starting TradePilot NSE End-of-Day automated sync & screening job...\\\")\\n    db = DatabaseManager()\\n    service = MarketDataService(db)\\n\\n    sync_res = service.refresh_stock_universe(force=force_refresh, fetch_fundamentals=True)\\n    logger.info(f\\\"Market data sync finished: {sync_res['details']}\\\")\\n\\n    pipe_res = run_full_screening_pipeline(db)\\n    logger.info(f\\\"Screening pipeline finished: Processed={pipe_res['processed']}, Skipped={pipe_res['skipped']}\\\")\\n\\n    trial_res = {\\\"skipped\\\": True}\\n    if run_paper_trial:\\n        trial_res = run_daily_paper_trial_step(db)\\n        logger.info(f\\\"Paper Trial step finished: {trial_res}\\\")\\n\\n    df = db.get_all_screening_results()\\n    csv_path = None\\n    if not df.empty:\\n        date_tag = now_ist().strftime(\\\"%Y%m%d\\\")\\n        csv_path = Path(EXPORTS_DIR) / f\\\"TradePilot_NSE_EOD_{date_tag}.csv\\\"\\n        xlsx_path = Path(EXPORTS_DIR) / f\\\"TradePilot_NSE_EOD_{date_tag}.xlsx\\\"\\n        df.to_csv(csv_path, index=False)\\n        try:\\n            df.to_excel(xlsx_path, index=False, engine=\\\"openpyxl\\\")\\n        except Exception as exc:\\n            logger.warning(f\\\"Excel export skipped: {exc}\\\")\\n        logger.info(f\\\"Saved EOD screening exports to {csv_path}\\\")\\n\\n    tg_res = {\\\"ok\\\": False, \\\"skipped\\\": True}\\n    if send_telegram:\\n        tg_res = dispatch_eod_telegram_alert(db, sync_summary=sync_res)\\n        if tg_res.get(\\\"ok\\\"):\\n            logger.info(\\\"Daily BUY WATCH Telegram alert sent successfully!\\\")\\n        elif tg_res.get(\\\"skipped\\\"):\\n            logger.info(f\\\"Telegram alert skipped: {tg_res.get('reason')}\\\")\\n        else:\\n            logger.warning(f\\\"Telegram alert failed: {tg_res.get('error')}\\\")\\n\\n    return {\\n        \\\"sync\\\": sync_res,\\n        \\\"pipeline\\\": pipe_res,\\n        \\\"paper_trial\\\": trial_res,\\n        \\\"csv_export\\\": str(csv_path) if csv_path else None,\\n        \\\"telegram\\\": tg_res,\\n    }\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser(description=\\\"TradePilot NSE End-of-Day Sync, Screener, Paper Trial & Telegram Notifier\\\")\\n    parser.add_argument(\\\"--force\\\", action=\\\"store_true\\\", help=\\\"Force full OHLCV download even if latest bar is cached\\\")\\n    parser.add_argument(\\\"--no-telegram\\\", action=\\\"store_true\\\", help=\\\"Skip sending Telegram notification\\\")\\n    parser.add_argument(\\\"--no-trial\\\", action=\\\"store_true\\\", help=\\\"Skip automated 1-Month Paper Trial step\\\")\\n    args = parser.parse_args()\\n\\n    run_eod_job(force_refresh=args.force, send_telegram=not args.no_telegram, run_paper_trial=not args.no_trial)\\n\"}")

def apply_update():
    base_dir = Path(__file__).resolve().parent
    if not (base_dir / "app.py").exists():
        print("[ERROR] Place apply_paper_trial_update.py inside your TradePilot_NSE folder (next to app.py).")
        return

    for rel_path, content in PATCH_FILES.items():
        target = base_dir / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        print(f"  [UPDATED] {rel_path}")

    print("\n[SUCCESS] 1-Month Paper Trial Journal added!")
    print("Restart run_tradepilot.bat and open '8. 1-Month Paper Trial Journal' in the sidebar.")

if __name__ == "__main__":
    apply_update()